import React,{useState} from 'react';
export default function Booking({state='ready'}){const [slot,setSlot]=useState('');const [selected,setSelected]=useState(false);if(state!=='ready')return <section className="state" data-state={state} role={state==='error'?'alert':'status'}><h2>{state==='loading'?'Loading context…':state==='empty'?'Nothing to show yet':'This view needs attention'}</h2><p>{state==='error'?'Refresh the authorized data source and try again.':'The workspace remains available.'}</p></section>;
return <div className="shell"><span className="eyebrow">Scheduling / Reference interaction</span><h1>A little space for a focused conversation.</h1><p>Choose a slot and review the next step.</p><div className="grid"><section className="panel"><h2>Wednesday</h2><div className="steps">{['09:30','11:00','14:30'].map(s=><button key={s} id={'time-'+s.replace(':','')} className={slot===s?'btn':'btn ghost'} onClick={()=>{setSlot(s);setSelected(false);}}>{s}</button>)}</div></section><section className="panel soft"><h2>Your selection</h2><p>{slot||'Choose an available reference time.'}</p><button id="select-slot" className="btn" disabled={!slot} onClick={()=>setSelected(true)}>Review selected slot</button><p id="result" role="status">{selected?'Slot selected: '+slot+'. This is not a confirmed booking. Connect an authorized booking capability to continue.':'No appointment has been booked.'}</p></section></div></div>;}
